/// <summary>
///     The <c>AVAsmmContactTitleGroup_smmContactTitleGroupTranslateButtonBtn_Extension</c> class is the execution FormControl for <c>DirNameAffix</c>
/// </summary>
[ExtensionOf(FormControlStr(smmContactTitleGroup, smmContactTitleGroupTranslateButton)) ]
final class AVAsmmContactTitleGroup_smmContactTitleGroupTranslateButtonBtn_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>Clicked</c> class.
/// </summary>
public void Clicked()
{
    FormRun                 formRun;
    FormDataSource          smmContactTitleGroupDS;
    smmContactTitleGroup    locsmmContactTitleGroup;

    SysTranslationHelper    sysTranslationHelper;

    formRun                 = this.formRun();
    smmContactTitleGroupDS  = formRun.dataSource('smmContactTitleGroup');
    locsmmContactTitleGroup = element.smmContactTitleGroup;

    sysTranslationHelper    = new SysTranslationHelper( tableNum(smmContactTitleGroup),
                                                        tableNum(AVAsmmContactTitleGroupTranslation)
                                                        );
    /*
    // this is to show smmContactTitleGroup.TitleId, which is not a/part of NaturalKey, in the SysTranslation grid form.
    // due to no unique index on EcoResAttribute table below line is required.
    // Please note that “setMainTableNaturalKeyFieldId” is a misnomer – it basically allows any (one) given field to be specified to appear in TranslationList form instead of the NaturalKey field
    */
    sysTranslationHelper.setMainTableNaturalKeyFieldId(fieldNum(smmContactTitleGroup, TitleId));

    sysTranslationHelper.launchTranslationDetailForm(locsmmContactTitleGroup.RecId);

    next Clicked();

    smmContactTitleGroupDS.research(true);
}
